<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import type { ApplicationOption, Resource, ServiceAccessGrant, ServiceIdentity, ServiceTechnicalRole, ServiceTechnicalRoleResource } from "../types";
import type { SecurityAdministrationStore } from "../use-security-administration";

const props = defineProps<{ store: SecurityAdministrationStore; applicationId: string; applicationName: string; initialSection: "identities" | "roles" | "assignments" | "request" | "approvals" }>();
const section = ref<"identities" | "roles" | "assignments" | "request" | "approvals">("identities");
const identities = ref<ServiceIdentity[]>([]), selectedIdentityId = ref("");
const roles = ref<ServiceTechnicalRole[]>([]), selectedRoleId = ref(""), roleResources = ref<ServiceTechnicalRoleResource[]>([]);
const resources = ref<Resource[]>([]), applications = ref<ApplicationOption[]>([]);
const grants = ref<ServiceAccessGrant[]>([]), receivedGrants = ref<ServiceAccessGrant[]>([]);
const targetApplicationId = ref(""), targetResources = ref<Resource[]>([]), targetRoles = ref<ServiceTechnicalRole[]>([]);
const requestKind = ref<"resource" | "role">("resource"), requestResourceId = ref(""), requestRoleId = ref("");
const statusFilter = ref<"ALL" | ServiceAccessGrant["status"]>("ALL");
const loading = ref(false), acting = ref<string | null>(null), error = ref(""), notice = ref("");
const identityName = ref(""), roleCode = ref(""), roleName = ref(""), createBusy = ref(false), secret = ref("");
const statusLabel: Record<ServiceAccessGrant["status"], string> = { PENDING: "Pendiente", APPROVED: "Aprobada", REJECTED: "Rechazada", REVOKED: "Revocada" };
const selectedIdentity = computed(() => identities.value.find((item) => item.id === selectedIdentityId.value));
const selectedRole = computed(() => roles.value.find((item) => item.id === selectedRoleId.value));
const selectedGrantList = computed(() => grants.value.filter((grant) => grant.serviceIdentityId === selectedIdentityId.value && (statusFilter.value === "ALL" || grant.status === statusFilter.value)));
const currentResources = computed(() => resources.value.filter((resource) => !roleResources.value.some((item) => item.id === resource.id)));
const appName = (id: string) => applications.value.find((application) => application.id === id)?.name ?? "Aplicación no disponible";
const assignmentLabel = (grant: ServiceAccessGrant) => {
  if (grant.technicalRoleId) return `Rol técnico · ${grant.technicalRole || "sin código"}`;
  const resource = [...resources.value, ...targetResources.value].find((item) => item.id === grant.resourceId);
  return resource ? `Recurso · ${resource.method} ${resource.path}` : "Recurso no disponible";
};
function message(cause: unknown, fallback: string) { return cause instanceof Error && cause.message ? cause.message : fallback; }
function date(value: string | null) { return value ? new Intl.DateTimeFormat("es-CO", { dateStyle: "medium" }).format(new Date(value)) : "—"; }
async function run(task: () => Promise<void>, fallback: string) { loading.value = true; error.value = ""; notice.value = ""; try { await task(); } catch (cause) { error.value = message(cause, fallback); } finally { loading.value = false; } }
async function loadIdentities() { await run(async () => { identities.value = await props.store.getServiceIdentities(); if (!selectedIdentityId.value && identities.value[0]) selectedIdentityId.value = identities.value[0].id; }, "No fue posible cargar las identidades de servicio."); }
async function loadRoles() { await run(async () => { roles.value = (await props.store.getServiceTechnicalRoles()).content; if (!selectedRoleId.value && roles.value[0]) selectedRoleId.value = roles.value[0].id; }, "No fue posible cargar los roles técnicos."); }
async function loadResources() { await run(async () => { resources.value = (await props.store.getServiceResources(props.applicationId)).content; }, "No fue posible cargar los recursos de la aplicación."); }
async function loadRoleResources() { if (!selectedRoleId.value) { roleResources.value = []; return; } await run(async () => { roleResources.value = (await props.store.getServiceTechnicalRoleResources(selectedRoleId.value)).content; }, "No fue posible cargar los recursos del rol técnico."); }
async function loadAssignments() { await run(async () => { const lists = await Promise.all(identities.value.map((identity) => props.store.getServiceAccessGrants(identity.id))); grants.value = lists.flat(); }, "No fue posible cargar las asignaciones de servicio."); }
async function loadApprovals() { await run(async () => { receivedGrants.value = await props.store.getReceivedServiceAccessGrants(); }, "No fue posible cargar las solicitudes recibidas."); }
async function loadApplications() { await run(async () => { applications.value = (await props.store.getServiceApplications()).content.filter((application) => application.id !== props.applicationId); }, "No fue posible cargar las aplicaciones destino."); }
async function loadTargetCatalog() { if (!targetApplicationId.value) { targetResources.value = []; targetRoles.value = []; return; } await run(async () => { const [nextResources, nextRoles] = await Promise.all([props.store.getServiceResources(targetApplicationId.value), props.store.getServiceTechnicalRolesForApplication(targetApplicationId.value)]); targetResources.value = nextResources.content; targetRoles.value = nextRoles.content; }, "No fue posible consultar los accesos de la aplicación destino."); }
async function select(sectionName: typeof section.value) { section.value = sectionName; error.value = ""; if (sectionName === "identities") await loadIdentities(); if (sectionName === "roles") { await loadRoles(); await loadResources(); } if (sectionName === "assignments") { if (!identities.value.length) await loadIdentities(); if (!applications.value.length) await loadApplications(); await loadAssignments(); } if (sectionName === "request") { if (!identities.value.length) await loadIdentities(); if (!applications.value.length) await loadApplications(); } if (sectionName === "approvals") await loadApprovals(); }
async function createIdentity() { if (!identityName.value.trim()) return; createBusy.value = true; try { const created = await props.store.createServiceIdentity(identityName.value.trim()); secret.value = created.clientSecret; identityName.value = ""; await loadIdentities(); notice.value = "Identidad creada. Guarde la credencial ahora; no volverá a mostrarse."; } catch (cause) { error.value = message(cause, "No fue posible crear la identidad."); } finally { createBusy.value = false; } }
async function createRole() { if (!roleCode.value.trim() || !roleName.value.trim()) return; createBusy.value = true; try { await props.store.createServiceTechnicalRole({ code: roleCode.value.trim(), name: roleName.value.trim(), resourceIds: [] }); roleCode.value = ""; roleName.value = ""; await loadRoles(); notice.value = "Rol técnico creado."; } catch (cause) { error.value = message(cause, "No fue posible crear el rol técnico."); } finally { createBusy.value = false; } }
async function addResource(resourceId: string) { if (!selectedRoleId.value) return; acting.value = resourceId; try { await props.store.addServiceTechnicalRoleResource(selectedRoleId.value, resourceId); await Promise.all([loadRoleResources(), loadRoles()]); } catch (cause) { error.value = message(cause, "No fue posible asociar el recurso."); } finally { acting.value = null; } }
async function removeResource(resourceId: string) { if (!selectedRoleId.value) return; acting.value = resourceId; try { await props.store.removeServiceTechnicalRoleResource(selectedRoleId.value, resourceId); await Promise.all([loadRoleResources(), loadRoles()]); } catch (cause) { error.value = message(cause, "No fue posible retirar el recurso."); } finally { acting.value = null; } }
async function requestAccess() { if (!selectedIdentityId.value || !targetApplicationId.value || (requestKind.value === "resource" ? !requestResourceId.value : !requestRoleId.value)) return; acting.value = "request"; try { await props.store.requestServiceAccess(selectedIdentityId.value, requestKind.value === "resource" ? { resourceId: requestResourceId.value } : { technicalRoleId: requestRoleId.value }); requestResourceId.value = ""; requestRoleId.value = ""; notice.value = "La solicitud quedó pendiente de aprobación por la aplicación dueña."; await select("assignments"); } catch (cause) { error.value = message(cause, "No fue posible enviar la solicitud."); } finally { acting.value = null; } }
async function decide(grant: ServiceAccessGrant, approve: boolean) { acting.value = grant.id; try { await props.store.decideServiceAccess(grant.id, approve); await loadApprovals(); } catch (cause) { error.value = message(cause, "No fue posible registrar la decisión."); } finally { acting.value = null; } }
async function revoke(grant: ServiceAccessGrant) { if (!window.confirm("¿Revocar este acceso aprobado?")) return; acting.value = grant.id; try { await props.store.revokeServiceAccess(grant.id); await loadApprovals(); } catch (cause) { error.value = message(cause, "No fue posible revocar el acceso."); } finally { acting.value = null; } }
watch(selectedRoleId, () => { void loadRoleResources(); });
watch(targetApplicationId, () => { requestResourceId.value = ""; requestRoleId.value = ""; void loadTargetCatalog(); });
watch(() => props.initialSection, (value) => { section.value = value; void select(value); });
onMounted(() => { void loadIdentities(); });
</script>

<template>
  <section class="service-admin" aria-label="Identidades de servicio">
    <div class="service-tabs" role="tablist" aria-label="Secciones de identidades de servicio"><button v-for="item in [{ id: 'identities', label: 'Identidades' }, { id: 'roles', label: 'Roles técnicos' }, { id: 'assignments', label: 'Asignaciones' }, { id: 'request', label: 'Solicitar acceso' }, { id: 'approvals', label: 'Aprobaciones' }]" :key="item.id" type="button" role="tab" :aria-selected="section === item.id" :class="{ active: section === item.id }" @click="select(item.id as typeof section)">{{ item.label }}</button></div>
    <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" class="success" role="status">{{ notice }}</p>

    <div v-if="section === 'identities'" class="service-content"><div class="section-title"><div><h5>Identidades de {{ applicationName }}</h5><p>Solo se muestran identidades cuyo consumidor es esta aplicación.</p></div><form class="inline-form" @submit.prevent="createIdentity"><input v-model="identityName" placeholder="Nombre de la nueva identidad" aria-label="Nombre de la nueva identidad" /><button class="primary" :disabled="createBusy || !identityName.trim()">{{ createBusy ? "Creando…" : "Crear identidad" }}</button></form></div><div v-if="secret" class="secret-box"><strong>Credencial generada</strong><code>{{ secret }}</code><small>Guárdela ahora. El PDP no volverá a mostrarla.</small></div><div class="panel"><div v-for="identity in identities" :key="identity.id" class="row"><div class="grow"><strong>{{ identity.name }}</strong><small>{{ identity.clientId }} · creada {{ date(identity.registeredAt) }}</small></div><span class="chip" :class="identity.status.toLowerCase()">{{ identity.status === 'ACTIVE' ? 'Activa' : identity.status === 'SUSPENDED' ? 'Suspendida' : 'Revocada' }}</span></div><p v-if="!loading && !identities.length" class="empty">Esta aplicación aún no tiene identidades de servicio.</p></div></div>

    <div v-else-if="section === 'roles'" class="service-content"><div class="section-title"><div><h5>Roles técnicos de {{ applicationName }}</h5><p>Defina agrupaciones de recursos que sus identidades podrán solicitar.</p></div><form class="role-create" @submit.prevent="createRole"><input v-model="roleCode" placeholder="Código" aria-label="Código del rol técnico" /><input v-model="roleName" placeholder="Nombre visible" aria-label="Nombre del rol técnico" /><button class="primary" :disabled="createBusy || !roleCode.trim() || !roleName.trim()">Crear rol</button></form></div><div class="role-layout"><div class="panel"><button v-for="role in roles" :key="role.id" type="button" class="role-choice" :class="{ selected: selectedRoleId === role.id }" @click="selectedRoleId = role.id"><strong>{{ role.name }}</strong><small>{{ role.code }} · {{ role.resourceCount }} recursos</small></button><p v-if="!loading && !roles.length" class="empty">No hay roles técnicos definidos.</p></div><div class="panel role-detail"><template v-if="selectedRole"><h5>{{ selectedRole.name }} <code>{{ selectedRole.code }}</code></h5><p class="sub">Recursos asociados</p><div v-for="resource in roleResources" :key="resource.id" class="row"><div class="grow"><strong>{{ resource.method }} {{ resource.path }}</strong></div><button class="quiet danger" :disabled="acting === resource.id" @click="removeResource(resource.id)">Retirar</button></div><label class="add-resource">Agregar recurso<select @change="addResource(($event.target as HTMLSelectElement).value)"><option value="">Seleccione un recurso</option><option v-for="resource in currentResources" :key="resource.id" :value="resource.id">{{ resource.method }} {{ resource.path }}</option></select></label><p v-if="!roleResources.length" class="empty compact">Este rol aún no tiene recursos.</p></template><p v-else class="empty">Seleccione un rol técnico para ver sus recursos.</p></div></div></div>

    <div v-else-if="section === 'assignments'" class="service-content"><div class="section-title"><div><h5>Asignaciones de las identidades</h5><p>Estado de los accesos solicitados por {{ applicationName }}. Las decisiones pertenecen a la aplicación dueña.</p></div><label>Identidad<select v-model="selectedIdentityId"><option v-for="identity in identities" :key="identity.id" :value="identity.id">{{ identity.name }}</option></select></label></div><div class="toolbar"><label>Estado<select v-model="statusFilter"><option value="ALL">Todas</option><option value="PENDING">Pendientes</option><option value="APPROVED">Aprobadas</option><option value="REJECTED">Rechazadas</option><option value="REVOKED">Revocadas</option></select></label><span>{{ selectedGrantList.length }} asignaciones mostradas</span></div><div class="panel"><div v-for="grant in selectedGrantList" :key="grant.id" class="row"><div class="grow"><strong>{{ assignmentLabel(grant) }}</strong><small>{{ appName(grant.targetApplicationId) }} · solicitada {{ date(grant.requestedAt) }} · decidida {{ date(grant.decidedAt) }}</small></div><span class="chip">{{ statusLabel[grant.status] }}</span></div><p v-if="!loading && !selectedGrantList.length" class="empty">Esta identidad no tiene asignaciones con el filtro seleccionado.</p></div></div>

    <div v-else-if="section === 'request'" class="service-content"><div class="section-title"><div><h5>Solicitar acceso para una identidad</h5><p>La solicitud se envía a la aplicación dueña del recurso o rol.</p></div></div><form class="request-form" @submit.prevent="requestAccess"><label>Identidad<select v-model="selectedIdentityId"><option value="">Seleccione una identidad</option><option v-for="identity in identities" :key="identity.id" :value="identity.id">{{ identity.name }}</option></select></label><label>Aplicación dueña<select v-model="targetApplicationId"><option value="">Seleccione una aplicación</option><option v-for="application in applications" :key="application.id" :value="application.id">{{ application.name }}</option></select></label><label>Tipo<select v-model="requestKind" :disabled="!targetApplicationId"><option value="resource">Recurso independiente</option><option value="role">Rol técnico</option></select></label><label v-if="requestKind === 'resource'">Recurso<select v-model="requestResourceId" :disabled="!targetApplicationId"><option value="">Seleccione un recurso</option><option v-for="resource in targetResources" :key="resource.id" :value="resource.id">{{ resource.method }} {{ resource.path }}</option></select></label><label v-else>Rol técnico<select v-model="requestRoleId" :disabled="!targetApplicationId"><option value="">Seleccione un rol</option><option v-for="role in targetRoles" :key="role.id" :value="role.id">{{ role.name }} · {{ role.code }}</option></select></label><button class="primary" :disabled="acting === 'request' || !selectedIdentityId || !targetApplicationId || (requestKind === 'resource' ? !requestResourceId : !requestRoleId)">{{ acting === 'request' ? 'Enviando…' : 'Enviar solicitud' }}</button></form></div>

    <div v-else class="service-content"><div class="section-title"><div><h5>Aprobaciones para {{ applicationName }}</h5><p>Solicitudes recibidas por recursos de esta aplicación. Aquí sí puede decidir como administrador dueño.</p></div></div><div class="panel"><div v-for="grant in receivedGrants" :key="grant.id" class="row"><div class="grow"><strong>{{ assignmentLabel(grant) }}</strong><small>Identidad {{ grant.serviceIdentityId.slice(0, 8) }} · solicitada {{ date(grant.requestedAt) }}</small></div><span class="chip">{{ statusLabel[grant.status] }}</span><div class="row-actions"><template v-if="grant.status === 'PENDING'"><button class="primary" :disabled="acting !== null" @click="decide(grant, true)">Aprobar</button><button class="quiet danger" :disabled="acting !== null" @click="decide(grant, false)">Rechazar</button></template><button v-if="grant.status === 'APPROVED'" class="quiet danger" :disabled="acting !== null" @click="revoke(grant)">Revocar</button></div></div><p v-if="!loading && !receivedGrants.length" class="empty">No hay solicitudes recibidas para esta aplicación.</p></div></div>
  </section>
</template>
